window.__PAGES=window.__PAGES||{};window.__PAGES["pages/contacts.html"]="<!-- Contacts Page — CRUD table with search, tag/channel filters, detail modal -->\n<style>\n.ct-actions{display:flex;gap:8px;align-items:center;margin-left:auto}\n.ct-search{padding:7px 14px;border:1px solid var(--border);border-radius:20px;font-size:13px;background:var(--bg);width:260px}\n.ct-search:focus{outline:2px solid var(--accent);outline-offset:-1px}\n.ct-tag-bar{display:flex;gap:6px;flex-wrap:wrap;align-items:center}\n.ct-channel-filter{margin-left:auto;display:flex;gap:6px}\n.ch-badge{display:inline-block;padding:2px 8px;border-radius:10px;font-size:11px;font-weight:600;background:#dbeafe;color:#2563eb}\n.ch-badge.web{background:#f3e8ff;color:#7c3aed}\n.ch-badge.api{background:#dbeafe;color:#2563eb}\n.tag-pill{display:inline-flex;align-items:center;gap:4px;padding:2px 8px;border-radius:10px;font-size:11px;font-weight:600;background:var(--bg);border:1px solid var(--border)}\n.tag-pill .x{cursor:pointer;font-size:13px;line-height:1;color:var(--muted);font-weight:700}\n.tag-pill .x:hover{color:var(--danger)}\n.empty-row td{text-align:center;padding:40px;color:var(--muted)}\n.ct-detail-row{display:flex;justify-content:space-between;padding:6px 0;border-bottom:1px solid var(--border)}\n.ct-detail-row:last-child{border:none}\n.ct-detail-k{font-size:12px;color:var(--muted)}.ct-detail-v{font-size:13px;font-weight:600}\n.ct-tag-list{display:flex;gap:6px;flex-wrap:wrap;margin-top:4px}\n.ct-conv-count{margin-top:12px;padding:10px;background:var(--bg);border-radius:8px;font-size:13px;text-align:center}\n.ct-del-confirm{background:#fef2f2;border:1px solid #fecaca;border-radius:8px;padding:12px;margin:10px 0;font-size:13px;color:var(--danger)}\n</style>\n\n<div class=\"page-header\">\n  <h1>📇 Kontak</h1>\n  <div class=\"ct-actions\">\n    <input class=\"ct-search\" id=\"ctSearch\" placeholder=\"Cari kontak…\" oninput=\"renderContacts()\">\n    <button class=\"btn primary\" onclick=\"openAddModal()\">+ Tambah Kontak</button>\n  </div>\n</div>\n\n<div class=\"page-filters\">\n  <div class=\"ct-tag-bar\" id=\"ctTagBar\"></div>\n  <div class=\"ct-channel-filter\">\n    <span class=\"filter-chip active\" data-ch=\"all\" onclick=\"setChannel(this)\">Semua</span>\n    <span class=\"filter-chip\" data-ch=\"whatsapp-api\" onclick=\"setChannel(this)\">🟢 WhatsApp API</span>\n    <span class=\"filter-chip\" data-ch=\"whatsapp-web\" onclick=\"setChannel(this)\">🔵 WhatsApp Web</span>\n  </div>\n</div>\n\n<div class=\"page-body\">\n  <table class=\"data-table\" id=\"ctTable\">\n    <thead><tr><th>Nama</th><th>Telepon</th><th>Channel</th><th>Tag</th><th>Terakhir Aktif</th><th></th></tr></thead>\n    <tbody id=\"ctBody\"></tbody>\n  </table>\n</div>\n\n<!-- Detail Modal -->\n<div class=\"modal-overlay\" id=\"detailModal\">\n  <div class=\"modal\" style=\"max-width:480px\">\n    <h3 id=\"dmName\">-</h3>\n    <div id=\"dmBody\"></div>\n    <div class=\"modal-actions\">\n      <button class=\"btn\" onclick=\"openEditFromDetail()\">✏️ Edit</button>\n      <button class=\"btn danger\" onclick=\"confirmDelete()\">🗑️ Hapus</button>\n      <button class=\"btn\" onclick=\"closeModal('detailModal')\">Tutup</button>\n    </div>\n  </div>\n</div>\n\n<!-- Add/Edit Modal -->\n<div class=\"modal-overlay\" id=\"formModal\">\n  <div class=\"modal\">\n    <h3 id=\"fmTitle\">Tambah Kontak</h3>\n    <label>Nama<input id=\"fmName\" placeholder=\"Nama lengkap\"></label>\n    <label>Telepon<input id=\"fmPhone\" placeholder=\"+628xxxx\"></label>\n    <label>Channel<select id=\"fmChannel\"><option value=\"whatsapp-api\">WhatsApp API</option><option value=\"whatsapp-web\">WhatsApp Web</option></select></label>\n    <label>Tag (pisahkan koma)<input id=\"fmTags\" placeholder=\"VIP, Pelanggan\"></label>\n    <div class=\"modal-actions\">\n      <button class=\"btn\" onclick=\"closeModal('formModal')\">Batal</button>\n      <button class=\"btn primary\" id=\"fmSave\" onclick=\"saveContact()\">Simpan</button>\n    </div>\n  </div>\n</div>\n\n<!-- Delete Confirm Modal -->\n<div class=\"modal-overlay\" id=\"delModal\">\n  <div class=\"modal\">\n    <h3>Hapus Kontak</h3>\n    <div class=\"ct-del-confirm\" id=\"delMsg\"></div>\n    <div class=\"modal-actions\">\n      <button class=\"btn\" onclick=\"closeModal('delModal')\">Batal</button>\n      <button class=\"btn danger\" onclick=\"doDelete()\">Hapus</button>\n    </div>\n  </div>\n</div>\n\n<!-- Tag Edit Modal -->\n<div class=\"modal-overlay\" id=\"tagModal\">\n  <div class=\"modal\" style=\"min-width:320px\">\n    <h3>Kelola Tag</h3>\n    <div id=\"tagList\" style=\"margin:8px 0\"></div>\n    <div style=\"display:flex;gap:8px;margin-top:8px\">\n      <input id=\"tagInput\" placeholder=\"Tag baru\" style=\"flex:1;padding:8px;border:1px solid var(--border);border-radius:8px;font-size:13px;background:var(--bg)\" onkeydown=\"if(event.key==='Enter')addTag()\">\n      <button class=\"btn primary\" onclick=\"addTag()\">Tambah</button>\n    </div>\n    <div class=\"modal-actions\"><button class=\"btn\" onclick=\"closeModal('tagModal')\">Tutup</button></div>\n  </div>\n</div>\n\n<script>\nlet activeChannel='all', activeTag='', editId=null, detailId=null;\n\n// Auto-populate from global search\nconst gs=window._globalSearch;\nif(gs){document.getElementById('ctSearch').value=gs}\n\nfunction renderTagBar(){\n  const allTags=[...new Set(DB.contacts.flatMap(c=>c.tags||[]))];\n  const bar=document.getElementById('ctTagBar');\n  bar.innerHTML='<span class=\"filter-chip'+(activeTag===''?' active':'')+'\" onclick=\"filterTag(\\'\\')\">Semua Tag</span>'+\n    allTags.map(t=>'<span class=\"filter-chip'+(activeTag===t?' active':'')+'\" onclick=\"filterTag(\\''+t+'\\')\">'+t+'</span>').join('');\n}\n\nfunction filterTag(t){activeTag=t;renderContacts()}\nfunction setChannel(el){\n  activeChannel=el.dataset.ch;\n  document.querySelectorAll('.ct-channel-filter .filter-chip').forEach(c=>c.classList.remove('active'));\n  el.classList.add('active');\n  renderContacts();\n}\n\nfunction renderContacts(){\n  const q=document.getElementById('ctSearch').value.toLowerCase();\n  let rows=DB.contacts.filter(c=>{\n    if(activeChannel!=='all'&&c.channel!==activeChannel)return false;\n    if(activeTag&&!((c.tags||[]).includes(activeTag)))return false;\n    if(q&&!c.name.toLowerCase().includes(q)&&!c.phone.includes(q))return false;\n    return true;\n  });\n  rows.sort((a,b)=>new Date(b.lastActive||0)-new Date(a.lastActive||0));\n  const tbody=document.getElementById('ctBody');\n  if(!rows.length){tbody.innerHTML='<tr class=\"empty-row\"><td colspan=\"6\">Tidak ada kontak ditemukan</td></tr>';return}\n  tbody.innerHTML=rows.map(c=>{\n    const ch=c.channel==='whatsapp-api'?'<span class=\"ch-badge api\">API</span>':'<span class=\"ch-badge web\">Web</span>';\n    const tags=(c.tags||[]).map(t=>'<span class=\"tag-pill\">'+t+'</span>').join(' ');\n    return '<tr style=\"cursor:pointer\" onclick=\"showDetail(\\''+c.id+'\\')\">'+\n      '<td><strong>'+esc(c.name)+'</strong></td>'+\n      '<td>'+esc(c.phone)+'</td>'+\n      '<td>'+ch+'</td>'+\n      '<td>'+(tags||'<span style=\"color:var(--muted)\">-</span>')+'</td>'+\n      '<td>'+fmtTime(c.lastActive)+' '+fmtDate(c.lastActive)+'</td>'+\n      '<td><button class=\"btn\" onclick=\"event.stopPropagation();openEditModal(\\''+c.id+'\\')\" style=\"font-size:11px\">✏️</button></td>'+\n    '</tr>';\n  }).join('');\n  renderTagBar();\n}\n\nfunction esc(s){const d=document.createElement('div');d.textContent=s;return d.innerHTML}\n\nfunction showDetail(id){\n  detailId=id;\n  const c=dbFind('contacts',id);if(!c)return;\n  document.getElementById('dmName').textContent=c.name;\n  const convCount=DB.conversations.filter(cv=>cv.contactId===id).length;\n  const tagsHtml=(c.tags||[]).map(t=>'<span class=\"tag-pill\">'+esc(t)+'<span class=\"x\" onclick=\"event.stopPropagation();removeTag(\\''+esc(t)+'\\')\">×</span></span>').join(' ');\n  document.getElementById('dmBody').innerHTML=\n    '<div class=\"ct-detail-row\"><span class=\"ct-detail-k\">Telepon</span><span class=\"ct-detail-v\">'+esc(c.phone)+'</span></div>'+\n    '<div class=\"ct-detail-row\"><span class=\"ct-detail-k\">Channel</span><span class=\"ct-detail-v\">'+(c.channel==='whatsapp-api'?'WhatsApp API':'WhatsApp Web')+'</span></div>'+\n    '<div class=\"ct-detail-row\"><span class=\"ct-detail-k\">Terakhir Aktif</span><span class=\"ct-detail-v\">'+fmtTime(c.lastActive)+' '+fmtDate(c.lastActive)+'</span></div>'+\n    '<div class=\"ct-detail-row\"><span class=\"ct-detail-k\">Tag</span><span class=\"ct-detail-v\">'+(tagsHtml||'<span style=\"color:var(--muted)\">-</span>')+\n    ' <button class=\"btn\" style=\"font-size:10px;padding:2px 8px;margin-left:6px\" onclick=\"openTagModal()\">+ Tag</button></span></div>'+\n    '<div class=\"ct-conv-count\">💬 '+convCount+' percakapan tercatat</div>';\n  openModal('detailModal');\n}\n\nfunction openAddModal(){\n  editId=null;\n  document.getElementById('fmTitle').textContent='Tambah Kontak';\n  document.getElementById('fmName').value='';\n  document.getElementById('fmPhone').value='';\n  document.getElementById('fmChannel').value='whatsapp-api';\n  document.getElementById('fmTags').value='';\n  openModal('formModal');\n}\n\nfunction openEditModal(id){\n  editId=id;\n  const c=dbFind('contacts',id);if(!c)return;\n  document.getElementById('fmTitle').textContent='Edit Kontak';\n  document.getElementById('fmName').value=c.name;\n  document.getElementById('fmPhone').value=c.phone;\n  document.getElementById('fmChannel').value=c.channel;\n  document.getElementById('fmTags').value=(c.tags||[]).join(', ');\n  openModal('formModal');\n}\n\nfunction openEditFromDetail(){\n  closeModal('detailModal');\n  if(detailId)openEditModal(detailId);\n}\n\nfunction saveContact(){\n  const name=document.getElementById('fmName').value.trim();\n  const phone=document.getElementById('fmPhone').value.trim();\n  const channel=document.getElementById('fmChannel').value;\n  const tags=document.getElementById('fmTags').value.split(',').map(s=>s.trim()).filter(Boolean);\n  if(!name||!phone){showToast('Nama dan telepon wajib diisi');return}\n  if(editId){\n    dbUpdate('contacts',editId,{name,phone,channel,tags});\n    showToast('Kontak diperbarui');\n  }else{\n    dbAdd('contacts',{id:genId('c'),name,phone,channel,tags,lastActive:new Date().toISOString()});\n    showToast('Kontak ditambahkan');\n  }\n  closeModal('formModal');\n  renderContacts();\n}\n\nfunction confirmDelete(){\n  if(!detailId)return;\n  const c=dbFind('contacts',detailId);\n  document.getElementById('delMsg').textContent='Yakin ingin menghapus kontak \"'+c?.name+'\"? Tindakan ini tidak dapat dibatalkan.';\n  closeModal('detailModal');\n  openModal('delModal');\n}\n\nfunction doDelete(){\n  if(!detailId)return;\n  dbRemove('contacts',detailId);\n  showToast('Kontak dihapus');\n  closeModal('delModal');\n  detailId=null;\n  renderContacts();\n}\n\n// Tag management\nfunction openTagModal(){\n  if(!detailId)return;\n  const c=dbFind('contacts',detailId);if(!c)return;\n  renderTagList(c);\n  document.getElementById('tagInput').value='';\n  openModal('tagModal');\n}\n\nfunction renderTagList(c){\n  const el=document.getElementById('tagList');\n  if(!c.tags||!c.tags.length){el.innerHTML='<span style=\"color:var(--muted);font-size:13px\">Belum ada tag</span>';return}\n  el.innerHTML=c.tags.map(t=>'<span class=\"tag-pill\">'+esc(t)+'<span class=\"x\" onclick=\"removeTag(\\''+esc(t)+'\\')\">×</span></span>').join(' ');\n}\n\nfunction addTag(){\n  if(!detailId)return;\n  const v=document.getElementById('tagInput').value.trim();\n  if(!v)return;\n  const c=dbFind('contacts',detailId);if(!c)return;\n  const tags=[...new Set([...(c.tags||[]),v])];\n  dbUpdate('contacts',detailId,{tags});\n  document.getElementById('tagInput').value='';\n  renderTagList(dbFind('contacts',detailId));\n  showToast('Tag ditambahkan');\n}\n\nfunction removeTag(tag){\n  if(!detailId)return;\n  const c=dbFind('contacts',detailId);if(!c)return;\n  const tags=(c.tags||[]).filter(t=>t!==tag);\n  dbUpdate('contacts',detailId,{tags});\n  renderTagList(dbFind('contacts',detailId));\n  showDetail(detailId); // refresh detail\n  renderContacts();\n  showToast('Tag dihapus');\n}\n\nfunction openModal(id){document.getElementById(id).classList.add('open')}\nfunction closeModal(id){document.getElementById(id).classList.remove('open')}\n\n// Init\nrenderContacts();\n</script>\n";
